"""Derive public synthetic-media evidence; preserve every ignored local run."""
from pathlib import Path
import hashlib
import json
import os
import re

repo = Path(__file__).resolve().parents[2]
scratch = repo / '.wac-local/WAC-M3-02'
destination = repo / 'docs/codex/winaudioclean/evidence'
destination.mkdir(exist_ok=True)


def sha_bytes(data):
    return hashlib.sha256(data).hexdigest()


def sanitize(value):
    if isinstance(value, str):
        for original, replacement in ((str(repo), '<repo>'), (str(Path.home()), '<user-profile>')):
            for variant in (original, original.replace('\\', '/'), original.replace('\\', '\\\\')):
                value = re.sub(re.escape(variant), lambda match: replacement, value, flags=re.I)
        value = re.sub(r'(<S N="(?:User|Computer|PSComputerName)">)[^<]*(</S>)', r'\1&lt;local-identity&gt;\2', value)
        for original, replacement in ((os.environ.get('USERNAME'), '<local-user>'), (os.environ.get('COMPUTERNAME'), '<local-computer>')):
            if original:
                value = re.sub(re.escape(original), lambda match: replacement, value, flags=re.I)
        return value
    if isinstance(value, dict):
        return {key: sanitize(item) for key, item in value.items()}
    if isinstance(value, list):
        return [sanitize(item) for item in value]
    return value


def write(name, value):
    path = destination / ('WAC-M3-02-media-' + name + '.json')
    if path.exists():
        raise ValueError('Refusing to replace existing public evidence: ' + path.name)
    data = (json.dumps(sanitize(value), indent=2, ensure_ascii=False, allow_nan=False) + '\n').encode('utf-8')
    path.write_bytes(data)
    record = {'path': path.relative_to(repo).as_posix(), 'sha256': sha_bytes(data), 'bytes': len(data)}
    print(json.dumps(record))
    return record


run_specs = [
    ('media-smoke', 'preliminary_scoped_pass', 'Filtered PS5.1 smoke; no final/unfiltered claim.'),
    ('media-final', 'preliminary_pass', 'A897 Batch; later native-error diagnostics gap was outside this passing media scope.'),
    ('media-final-corrected', 'preliminary_failure', 'CCA Batch; reserved PSHOST tag relay regression prevented ordinary batch publications.'),
    ('media-final-relay-fixed', 'preliminary_pass', 'DA98 Batch; passed ordinary media but later invalid relative manifest anchoring edge required a narrow C2CF fix.'),
    ('launcher-media-final', 'preliminary_pass', 'DA98 Batch/0FAC Launcher/6E27 BAT; six real full-app launcher cases passed before the C2CF anchoring fix.'),
    ('media-final-anchoring', 'final_api_acceptance', 'C2CF Batch/f01c main; final unfiltered API matrix on source-frozen runtime.'),
    ('launcher-media-final-anchoring', 'final_launcher_acceptance', 'C2CF Batch/0FAC Launcher/6E27 BAT; final six-case launcher integration on source-frozen runtime.'),
]
runs = []
logs = []
for folder, classification, reason in run_specs:
    base = scratch / folder
    path = base / 'summary.json'
    original = path.read_bytes()
    summary = json.loads(original.decode('utf-8'))
    if classification.startswith('final_'):
        if summary['status'] != 'pass' or not all(summary[key] for key in ('tools_unchanged', 'files_unchanged', 'copies_unchanged', 'sources_unchanged_during_run')):
            raise ValueError('Final matrix is not a completed stable pass: ' + folder)
        if summary['source_sha256_before']['WinAudioClean.Batch.ps1'] != 'c2cf3a3923e8608aaf0f010b18503d7cb282f040f465bb0c4f1b6ce89a0acdfc':
            raise ValueError('Unexpected final Batch bytes')
    runs.append({'run_id': folder, 'classification': classification, 'reason': reason,
                 'capture_scope_note': ('API-only capture includes main/IO/Preview/Settings/Batch and development utilities. The inherited raw summary says unfinished BAT/Launcher because the harness was authored earlier; at final C2CF execution those components were final/frozen but outside this API scope. Separate final launcher evidence captures all seven runtime/BAT files.' if folder.startswith('media-') else 'Separate launcher/application scope captures all seven runtime/BAT files, copied source and development utilities.'),
                 'local_summary_path': path.relative_to(repo).as_posix(), 'local_summary_sha256': sha_bytes(original),
                 'summary': summary})
    for local_log in sorted((base / 'logs').glob('*.txt')):
        original_log = local_log.read_bytes()
        public_text = sanitize(original_log.decode('utf-8'))
        logs.append({'run_id': folder, 'local_log_path': local_log.relative_to(repo).as_posix(),
                     'local_original_file_sha256': sha_bytes(original_log),
                     'published_utf8_text_sha256': sha_bytes(public_text.encode('utf-8')),
                     'published_text': public_text})

derivation = {'script': Path(__file__).relative_to(repo).as_posix(), 'source_sha256': sha_bytes(Path(__file__).read_bytes()),
              'policy': 'Public derivatives redact repository/profile paths, CLIXML User/Computer identities and local username/machine strings. Local original summaries/logs stay untouched. Log hashes describe generated local log files, not unretained native raw streams. Audio, binary PCM and full private reports are not published.',
              'synthetic_only': True, 'listening_or_active_ctrl_c_approval': False}
public = []
public.append(write('api', {'task': 'WAC-M3-02', 'derivation': derivation, **next(run for run in runs if run['classification'] == 'final_api_acceptance')}))
public.append(write('launcher', {'task': 'WAC-M3-02', 'derivation': derivation, **next(run for run in runs if run['classification'] == 'final_launcher_acceptance')}))
public.append(write('preliminary', {'task': 'WAC-M3-02', 'derivation': derivation, 'scope': 'Historical completed preliminary runs, with original source/copy/command/outcome digests retained; none is final C2CF acceptance.', 'runs': [run for run in runs if run['classification'].startswith('preliminary')]}))
harnesses = []
for filename in ('test-batch-media.py', 'test-launcher-media.py', 'publish-media-evidence.py'):
    path = scratch / filename
    original = path.read_bytes()
    public_source = sanitize(original.decode('utf-8'))
    harnesses.append({'development_only': True, 'local_path': path.relative_to(repo).as_posix(),
                      'local_physical_sha256': sha_bytes(original), 'published_utf8_source_sha256': sha_bytes(public_source.encode('utf-8')),
                      'source_utf8_text': public_source,
                      'replay_note': 'Save source_utf8_text as UTF-8 preserving its recorded newlines in the indicated ignored M3-02 path. Use the recorded command with a fresh output directory and the same pinned build. Runtime files and helper/baseline source must match recorded hashes.'})
public.append(write('harnesses', {'task': 'WAC-M3-02', 'derivation': derivation, 'harnesses': harnesses}))
public.append(write('logs', {'task': 'WAC-M3-02', 'derivation': derivation, 'log_count': len(logs), 'text_logs': logs}))
manifest = {'task': 'WAC-M3-02', 'derivation': derivation, 'public_files': public,
            'local_runs': [{key: value for key, value in run.items() if key != 'summary'} for run in runs]}
write('manifest', manifest)
pattern = re.compile(r'c:[\\/]users[\\/]|c:[\\/]projects[\\/]WinAudioClean-governance', re.I)
private_terms = [os.environ.get('USERNAME'), os.environ.get('COMPUTERNAME')]
for path in destination.glob('WAC-M3-02-media-*.json'):
    text = path.read_text(encoding='utf-8')
    if pattern.search(text) or any(term and term.lower() in text.lower() for term in private_terms):
        raise ValueError('Privacy scan failed: ' + path.name)
print('Public privacy scan passed; original local run files preserved.')
